/** Apple Pay entitlements are generated by the official plugin only when a real Merchant ID is supplied. */
module.exports = ({ config }) => {
  const merchantIdentifier = (process.env.EXPO_PUBLIC_APPLE_MERCHANT_ID || '').trim();
  const publishableKey = (process.env.EXPO_PUBLIC_STRIPE_PUBLISHABLE_KEY || '').trim();
  const paymentMode = (process.env.EXPO_PUBLIC_PAYMENTS_MODE || 'test').trim();
  if (!['test', 'live'].includes(paymentMode)) throw new Error('El modo de pagos debe ser test o live.');
  // Account payments receive their public key from the authenticated backend.
  // Keep the optional embedded TEST key for the independent diagnostic flow.
  if (publishableKey && !/^pk_test_[A-Za-z0-9]{12,}$/.test(publishableKey) && !(paymentMode === 'live' && /^pk_live_[A-Za-z0-9]{12,}$/.test(publishableKey))) throw new Error('La clave publicable no corresponde a un modo de pagos permitido.');
  if (merchantIdentifier && !/^merchant\.[A-Za-z0-9][A-Za-z0-9.-]{2,199}$/.test(merchantIdentifier)) throw new Error('El Merchant ID de Apple Pay no tiene un formato válido.');
  const configuredPlugins = config.plugins || [];
  const buildOptions = configuredPlugins.reduce((merged, plugin) => {
    if (!Array.isArray(plugin) || plugin[0] !== 'expo-build-properties') return merged;
    const options = plugin[1] || {};
    return { ...merged, ...options, android: { ...merged.android, ...options.android }, ios: { ...merged.ios, ...options.ios } };
  }, {});
  const plugins = configuredPlugins.filter(plugin => !['@stripe/stripe-react-native', 'expo-build-properties'].includes(Array.isArray(plugin) ? plugin[0] : plugin));
  // Stripe 0.81 resolves its iOS SDK through SPM, which requires dynamic linkage
  // even when this build has no Apple Pay merchant entitlement configured.
  plugins.push(['expo-build-properties', { ...buildOptions, ios: { ...buildOptions.ios, useFrameworks: 'dynamic' } }]);
  if (merchantIdentifier) plugins.push(['@stripe/stripe-react-native', { merchantIdentifier, enableGooglePay: false }]);
  const infoPlist = config.ios?.infoPlist || {};
  return {
    ...config, plugins,
    extra: { ...config.extra, walletPaymentMode: paymentMode, walletPaymentMerchantIdentifier: merchantIdentifier },
    ios: { ...config.ios, infoPlist: { ...infoPlist, CFBundleAllowMixedLocalizations: true, CFBundleLocalizations: [...new Set([...(Array.isArray(infoPlist.CFBundleLocalizations) ? infoPlist.CFBundleLocalizations : []), 'es'])] } },
  };
};
